// Generated by scripts/sync-core.mts from packages/core/src. Do not edit; run `pnpm sync:core`.
import type { SupabaseClient } from "@supabase/supabase-js";
import type { PrivateLessonsConfig } from "../ai/config-schema.ts";
import type { ConfigReader } from "../ai/config-schema.ts";
import type { Database, Json } from "../db/types.ts";
import type { LessonSpec } from "../dsl/schema.ts";
import type { SourceChunk } from "./pipeline.ts";

// Private lessons from a student's own materials (10 MVP-02): which outline topics their materials
// cover, the chunks that ground a lesson, publishing it, and queueing the jobs. Service role only;
// every call is scoped to one student (guardrail 7). Shared lessons never come through here.

/** Where the materials live: a course, or a free-standing topic (courseId null). */
export type PrivateScope = { userId: string; courseId: string | null };

export type PrivateLessonPayload = {
  concept_id: string;
  course_id: string | null;
  user_id: string;
  private: true;
};

export type ItemsGenPayload = {
  concept_id: string;
  lesson_id: string;
  course_id: string | null;
  /** Set for items grounded in the student's own materials (a private lesson). */
  owner_id: string | null;
};

export const privateLessonDedupe = (userId: string, conceptId: string, courseId: string | null) =>
  `lesson:private:${userId}:${conceptId}:${courseId ?? "topic"}`;
export const itemsDedupe = (lessonId: string) => `items:${lessonId}`;

export interface PrivateLessonRepo {
  config(): Promise<PrivateLessonsConfig>;
  /** Close chunks per concept: every outline topic of the course, or the one topic. */
  coverage(scope: PrivateScope, conceptId: string | null, cfg: PrivateLessonsConfig): Promise<Map<string, number>>;
  sources(scope: PrivateScope, conceptId: string, cfg: PrivateLessonsConfig): Promise<SourceChunk[]>;
  /** Published private lesson ids per concept for this student and scope. */
  publishedConcepts(scope: PrivateScope): Promise<Set<string>>;
  publish(args: {
    scope: PrivateScope;
    conceptId: string;
    spec: LessonSpec;
    status: "published" | "review";
    sourceRefs: number[];
    model: string;
  }): Promise<string>;
  /** Reserve one private lesson from the student's daily allowance; false when used up. */
  reserve(userId: string): Promise<boolean>;
  refund(userId: string): Promise<void>;
  /** Queue a private lesson job; created = false when one is already queued or running. */
  enqueueLesson(scope: PrivateScope, conceptId: string): Promise<{ jobId: string; created: boolean }>;
  enqueueItems(payload: ItemsGenPayload): Promise<void>;
}

export function createSupabasePrivateLessonRepo(db: SupabaseClient<Database>, config: ConfigReader): PrivateLessonRepo {
  const nullable = (v: string | null) => v as unknown as string;
  return {
    config: () => config("private_lessons"),

    async coverage(scope, conceptId, cfg) {
      const { data, error } = await db.rpc("material_coverage", {
        p_user: scope.userId,
        p_course: nullable(scope.courseId),
        p_concept: nullable(scope.courseId ? null : conceptId),
        p_min_similarity: cfg.min_similarity,
      });
      if (error) throw new Error("Couldn't check material coverage");
      return new Map((data ?? []).map((r) => [r.concept_id, r.close_chunks]));
    },

    async sources(scope, conceptId, cfg) {
      const { data, error } = await db.rpc("private_lesson_sources", {
        p_user: scope.userId,
        p_course: nullable(scope.courseId),
        p_concept: conceptId,
        p_min_similarity: cfg.min_similarity,
        p_limit: cfg.max_chunks,
      });
      if (error) throw new Error("Couldn't load the student's materials");
      // Page order reads like the notes themselves.
      return (data ?? [])
        .map((c) => ({ id: Number(c.id), content: c.content, page: c.page }))
        .sort((a, b) => (a.page ?? 0) - (b.page ?? 0) || a.id - b.id);
    },

    async publishedConcepts(scope) {
      let q = db
        .from("lessons")
        .select("concept_id")
        .eq("owner_id", scope.userId)
        .in("status", ["published", "review"]);
      q = scope.courseId ? q.eq("course_id", scope.courseId) : q.is("course_id", null);
      const { data, error } = await q;
      if (error) throw new Error("Couldn't load private lessons");
      return new Set((data ?? []).map((r) => r.concept_id));
    },

    async publish(a) {
      const { data, error } = await db.rpc("publish_private_lesson", {
        p_owner: a.scope.userId,
        p_concept: a.conceptId,
        p_course: nullable(a.scope.courseId),
        p_spec: a.spec as unknown as Json,
        p_status: a.status,
        p_source_refs: a.sourceRefs,
        p_sources_used: a.sourceRefs.length,
        p_model: a.model,
      });
      if (error || !data) throw new Error("Couldn't publish the private lesson");
      return data;
    },

    async reserve(userId) {
      const limit = (await config("ai_quotas")).private_lesson?.limit ?? 0;
      const { data, error } = await db.rpc("consume_quota", {
        p_user: userId,
        p_feature: "private_lesson",
        p_limit: limit,
      });
      if (error) throw new Error("Couldn't reserve the allowance");
      return Boolean(data);
    },

    async refund(userId) {
      await db.rpc("refund_quota", { p_user: userId, p_feature: "private_lesson" });
    },

    async enqueueLesson(scope, conceptId) {
      const payload: PrivateLessonPayload = {
        concept_id: conceptId,
        course_id: scope.courseId,
        user_id: scope.userId,
        private: true,
      };
      const { data, error } = await db.rpc("enqueue_job_once", {
        p_queue: "lesson_gen",
        p_payload: payload as unknown as Json,
        p_dedupe: privateLessonDedupe(scope.userId, conceptId, scope.courseId),
        p_owner: scope.userId,
      });
      const row = data?.[0];
      if (error || !row) throw new Error("Couldn't queue the lesson");
      return { jobId: row.job_id, created: row.created };
    },

    async enqueueItems(payload) {
      const { error } = await db.rpc("enqueue_job_once", {
        p_queue: "items_gen",
        p_payload: payload as unknown as Json,
        p_dedupe: itemsDedupe(payload.lesson_id),
        p_owner: payload.owner_id ?? undefined,
      });
      if (error) throw new Error("Couldn't queue practice questions");
    },
  };
}

export type QueueResult = { queued: string[]; skipped: { conceptId: string; reason: "quota" }[] };

/**
 * After a student's materials are ready: queue a private lesson for every topic they cover that
 * has none yet, one allowance each, stopping when the day's allowance is used up (10 MVP-02).
 * The allowance is reserved before the job exists and refunded if the job already existed.
 */
export async function queuePrivateLessons(
  repo: PrivateLessonRepo,
  scope: PrivateScope,
  conceptId: string | null,
): Promise<QueueResult> {
  const cfg = await repo.config();
  const [coverage, existing] = await Promise.all([repo.coverage(scope, conceptId, cfg), repo.publishedConcepts(scope)]);
  const result: QueueResult = { queued: [], skipped: [] };
  for (const [concept, close] of coverage) {
    if (close < cfg.min_chunks || existing.has(concept)) continue;
    if (!(await repo.reserve(scope.userId))) {
      result.skipped.push({ conceptId: concept, reason: "quota" });
      continue;
    }
    const { created } = await repo.enqueueLesson(scope, concept);
    if (created) result.queued.push(concept);
    else await repo.refund(scope.userId);
  }
  return result;
}
